                        int p_mas = min(i + jump[k], Y);
                        int p_money = max(0, ivent[p_mas].sc + j);
                        p_mas = min(p_mas + ivent[p_mas].fr, Y);
                        dp[p_mas][p_money] += dp[i][j] / X;
                    }
                }
            }
        }

